#!/usr/bin/env python3
"""Freeze component qualification without promoting it to gameplay evidence."""
import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
native=json.loads((H/'native-v7/manifest.json').read_text())
host=json.loads((H/'host-v1/result.json').read_text())
assert native['status']==host['status']=='PASS'and not native['failures']
for result in [native,host]:
 for p,want in result['inputs_sha256'].items():assert sha(Path(p))==want,p
vectors=json.loads((H/'native-v7/inputs.json').read_text());scene=[v for v in vectors if v['name'].startswith('scene-')]
inputs=[H/p for p in ['async_mesh_repair.c','async_mesh_repair.h','make_reference.py','run_native.py','native_test.c','run_host.py','test_host.c','native-v7/manifest.json','native-v7/result.json','native-v6/manifest.json','host-v1/result.json','app-review-v1.json','compiled-app-math-v1.json','development-history-v1.json']]+[Path(__file__)]
record={'status':'PASS_COMPONENT_QUALIFICATION','inputs_sha256':{str(p):sha(p)for p in inputs},'native':{'tasks':native['vectors'],'exact_ordinary_words':native['compared_words'],'captured_geometry_tasks':len(scene),'captured_source_vertices':sum(v['count']for v in scene),'captured_raw_words':8*sum(v['count']for v in scene),'captured_input_triangles':sum(sum(1+(c[0]>>24==6)for c in v['commands'])for v in scene),'scene_tasks_exercising_full_raw_recompute_repair':sum(not v['raw_valid']for v in scene),'randomized_tasks':512,'special_raw_failure_tasks':34,'mismatches':0,'fcsr_restored':True,'target':'Exact current frozen Vexii native CPU model; reduced-FMA behavior is included.'},'host':{'tasks':host['tasks'],'checks':host['checks'],'sanitizers':host['sanitizers'],'checks_scope':'Packet bounds/format, clipping capacity, callback cancellation at every selected output prefix, malformed-input zero emission, caller rounding mode/exception preservation.'},'reference':{'clip_cull_projection_quantization_packing':'Mechanically extracted unchanged baseline functions, compiled with original fast-math flags. Source hashes and extracted fragment hashes are in native-v7/reference.json.','scalar_raw_failure':'Original executable instruction DAG, independently assembled after discovering that a reduced fast-math source extraction changes compiler reassociation/NaN comparisons. All scene rows additionally match the separately captured actual raw results.','material':'Uniform controlled textured/untextured, shaded/constant RGB565, tile bias/origin/alpha/projection cases. These vectors do not establish real shader setup or texture ownership.'},'correctness_details':['UV transform preserves fused (value-origin)*0.03125+bias, including clipped fractional UV.','W admission preserves the original executable FLE rejection guards, including unordered W behavior; equal W uses the direct packet path.','Clipped fan order, six-plane strict-inside tests, interpolated color truncation and direct perspective scale match the reference.','No renderer globals, heap allocation, SDK ring calls or mutable material lookups exist in the helper. Only the supplied emit callback owns output progress.','Caller must couple cancellation with consumer/output reset; it must not send END after a cancelled partial packet.','App supplies immutable original source bytes/context for raw failure, and a complete current raw snapshot otherwise; raw/context lifetime belongs to the worker.'],'remaining_gates':['Same-ELF complete native CPU+geometry+raster interval correctness and elapsed cycles.','Actual integrated reset/repair/lease/output-order protocol checks.','Physical area/timing only if measured full-frame benefit warrants it; no claim here.']}
out=H/'qualification-v1.json';assert not out.exists();out.write_text(json.dumps(record,indent=2)+'\n')
(H/'REPORT.txt').write_text('Pure async mesh repair component qualification: PASS.\n\nThe exact frozen CPU passed 1,184 tasks and 66,348 ordinary GPU words: all 638 captured geometry tasks (8,068 vertices / 64,544 raw words), 512 randomized cases, and 34 raw-failure boundary cases. This includes partial clipping, equal/negative W, NaN/Inf/subnormal inputs, quantization and FCSR preservation. The host ASan/UBSan suite passed 442,190 checks, including malformed-input zero output and cancellation at every selected packet prefix.\n\nThe final helper is async_mesh_repair.c/.h. Build its translation unit with -fno-fast-math -ffp-contract=off; target arithmetic instructions are explicit. It performs no allocation or renderer state lookup and emits only through its callback. Caller owns worker token, frozen source/context, output ordering and coupled reset.\n\nThese are component arithmetic/ownership-contract tests with controlled uniform materials. They are not a full-frame performance, real shader setup, physical fit or hardware FPS result. The final app math and read-only lifetime review are separately hash-bound. Qualification input/output hashes and limitations are in qualification-v1.json. Failed development runs remain recorded in development-history-v1.json; only native-v6/native-v7 and host-v1 are selected final helper evidence.\n')
print(out,sha(out))
